{
  "name": "opencode-ruby-upgrader",
  "version": "0.1.19",
  "description": "A safe, evidence-driven Ruby runtime upgrade agent and local migration dashboard for OpenCode",
  "author": "Priscilla Cournoyer (https://github.com/lilla021)",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/lilla021/opencode-ruby-upgrader.git"
  },
  "bugs": {
    "url": "https://github.com/lilla021/opencode-ruby-upgrader/issues"
  },
  "homepage": "https://github.com/lilla021/opencode-ruby-upgrader#readme",
  "type": "module",
  "main": "./src/index.js",
  "bin": {
    "opencode-ruby-upgrader": "./bin/opencode-ruby-upgrader.mjs"
  },
  "scripts": {
    "test": "node --test tests/*.test.js",
    "test:docker": "node tests/docker-adapter-smoke.mjs",
    "test:docker:mysql": "node tests/docker-adapter-smoke.mjs mysql",
    "test:docker:postgres": "node tests/docker-adapter-smoke.mjs postgres",
    "test:opencode": "node tests/opencode-runtime-smoke.mjs"
  },
  "allowScripts": {
    "opencode-ai@1.18.30": true
  },
  "files": [
    "src",
    "agents",
    "bin",
    "README.md",
    "LICENSE",
    "SECURITY.md",
    "PRIVACY.md",
    "RELEASING.md",
    "RELEASE_CHECKLIST.md",
    "RELEASE_NOTES.md",
    "E2E_EVIDENCE.md",
    "docs/bundler-bridge.md",
    "docs/rails-bridge.md"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "ruby",
    "rails",
    "upgrade",
    "worktree",
    "migration"
  ],
  "engines": {
    "node": ">=22.5.0"
  },
  "license": "MIT",
  "publishConfig": {
    "access": "public"
  }
}
